  static Future<void> removeWord(Word word) async {
    words.remove(word);
    await saveWords();
  }

  static Future<void> addLanguage(String language) async {
    if (!languages.contains(language)) {
      languages.add(language);
      await saveLanguages();
    }
  }

  static Future<void> removeLanguage(String language) async {
    if (languages.remove(language)) {
      words.removeWhere((w) => w.language_id == language);
      await saveLanguages();
      await saveWords();
    }
  }

  static Future<void> update() async {
    await saveWords();
  }

  static List<Word> getWordsForLanguage(String language) {
    return words.where((w) => w.language_id == language).toList();
  }

  static List<Word> getWordsForSearch(String currentLanguage, String searchInput) {
    return words.where((w) {
      bool matchesExactly =
          w.term.toLowerCase().contains(searchInput) ||
          w.definition.toLowerCase().contains(searchInput);
      bool matchesMostly =
          partialRatio(searchInput.toLowerCase(), w.term.toLowerCase()) > 85 ||
          partialRatio(searchInput.toLowerCase(), w.definition.toLowerCase()) > 85;
      return w.language_id == currentLanguage && (matchesExactly || matchesMostly);
    }).toList();
  }
}
